PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?scenario ?avgNewAllocationPct ?avgTargetAllocationPct
WHERE {
  {
    SELECT ?investorId ?scenario (AVG(xsd:decimal(?newAllocationPct)) AS ?avgNewAllocationPct)
    WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:investorId ?investorId ;
          wm:scenario ?scenario ;
          wm:newAllocationPct ?newAllocationPct .
    }
    GROUP BY ?investorId ?scenario
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?targetAllocationPct)) AS ?avgTargetAllocationPct)
    WHERE {
      ?ra a wm:RebalancingAction ;
          wm:investorId ?investorId ;
          wm:targetAllocationPct ?targetAllocationPct .
    }
    GROUP BY ?investorId
  }
}

