PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?type ?label ?count WHERE {
  {
    SELECT ( "Logic" AS ?type ) ?logic ?logicLabel (COUNT(?ra) AS ?count)
    WHERE {
      ?ra a wm:RebalancingAction ;
          wm:hasRebalancingLogic ?logic .
      OPTIONAL { ?logic rdfs:label ?logicLabel . }
    }
    GROUP BY ?logic ?logicLabel
  }
  UNION
  {
    SELECT ( "Scenario" AS ?type ) ?scenario ?scenarioLabel (COUNT(?sr) AS ?count)
    WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:hasMarketScenario ?scenario .
      OPTIONAL { ?scenario rdfs:label ?scenarioLabel . }
    }
    GROUP BY ?scenario ?scenarioLabel
  }
  BIND(COALESCE(?logicLabel, ?scenarioLabel) AS ?label)
}

